INTERNAL_METRICS={'Cuadro 12':'PIB real (variación anual %)','Cuadro 13':'Inflación (variación anual %)','Cuadro 15':'PIB nominal (variación anual %)','Cuadro 16':'Saldo primario (%PIB)','Cuadro 17':'Deuda (%PIB)','Cuadro 18':'Intereses (%PIB)'}
INTERNAL_PERIODS=['Promedio 2000-2024','Promedio 2025-2030','Promedio 2031-2040','Promedio 2041-2050']
def internal_rows(c,resolver,data):
 admitted=set(c.execute('SELECT * FROM family_usable_keys').fetchall());q=c.execute("SELECT * FROM table_observations WHERE book='2025'");names=[n[0]for n in q.description];published={(r['source_sheet'],r['source_cell']):r for r in[dict(zip(names,v))for v in q.fetchall()]};rows=[];s=resolver.sources['2025']
 for row in data:
  block=row['bloque'];cell=row['celda_valor'];match=re.fullmatch('([I-L])(7|8|9|10|11|12|13)',cell or'')
  if row['book']!='2025'or block not in INTERNAL_METRICS or match is None:continue
  col,rr=match[1],int(match[2]);require(row['hoja_valor']==block and(row['book'],row['row_number'])not in admitted,'Internal input/public admission collision');require(s.text(block,'I5')==INTERNAL_METRICS[block]and[s.text(block,x+'6')for x in'IJKL']==INTERNAL_PERIODS,'Internal metric/period headers changed');scenario=s.text(block,'C'+str(rr));require(isinstance(scenario,str)and scenario.strip(),'Internal scenario header missing');require(s.text(block,'C7')=='Base','Internal baseline scenario changed');require(row['metrica_literal']==INTERNAL_METRICS[block]and row['serie_literal']==scenario and row['periodo_categoria_literal']==s.text(block,col+'6'),'Internal original semantic metadata conflict');raw=s.number(block,cell);require(raw is not None and raw==Decimal(row['decimal_XML_texto']),'Internal exact XML value mismatch');base=col+'7';base_value=s.number(block,base);pi='DEFG'['IJKL'.index(col)]+str(rr);published_raw=None;published_key=None;formula=None;residual=None;marker=None
  if rr==7:
   formula='='+cell;require(s.text(block,pi)==formula,'Internal baseline link formula changed');published_raw=s.number(block,pi);residual=published_raw-raw;relation='published_base_level';role='base_period_average'
  elif col=='I':
   require(s.text(block,pi)=='..'and abs(raw-base_value)<=Decimal('1e-14'),'Internal historical average/marker changed');marker='..';relation='historical_marker_not_published_numeric_value';role='scenario_repeated_historical_average_not_independent_fact'
  else:
   formula='='+cell+'-'+base;require(s.text(block,pi)==formula,'Internal scenario difference formula changed');published_raw=s.number(block,pi);residual=published_raw-(raw-base_value);relation='published_change_from_base_not_input_level';role='scenario_future_period_average_not_published_level'
  if formula:
   require(residual is not None and abs(residual)<=Decimal('1e-14'),'Internal published formula cache residual');canonical=published[block,pi];published_key=(canonical['book'],canonical['row_number']);require(published_key in admitted and canonical['raw_value']==published_raw,'Internal published canonical link changed')
  unit='percent_annual_change_as_labelled'if block in['Cuadro 12','Cuadro 13','Cuadro 15']else'percent_gdp';proof=dict(scope='internal_model_input_period_average_value_not_published_fact',metric_cell='I5',scenario_cell='C'+str(rr),period_cell=col+'6',unit=unit,raw_input=str(raw),base_input_cell=base,base_input_value=str(base_value),published_cell=pi,published_formula=formula,published_marker=marker,published_raw_value=str(published_raw)if published_raw is not None else None,formula_residual=str(residual)if residual is not None else None,tolerance='1e-14',publication_relation=relation,not_public_lookup=True,identity='book,block,scenario,period,source_cell; never deduplicate by value alone')
  d=dict(book='2025',row_number=row['row_number'],record_id=row['id'],block=block,metric=INTERNAL_METRICS[block],scenario=scenario,period_literal=s.text(block,col+'6'),unit=unit,raw_value=raw,value=raw,source_sheet=block,source_cell=cell,metric_cell='I5',scenario_cell='C'+str(rr),period_cell=col+'6',value_role=role,scope=proof['scope'],base_input_cell=base,base_input_value=base_value,published_cell=pi,published_formula=formula,published_raw_value=published_raw,published_reference_kind=relation,published_book=published_key[0]if published_key else None,published_row_number=published_key[1]if published_key else None,formula_residual=residual,universal_metric=row['metrica_literal'],universal_series=row['serie_literal'],universal_category=row['periodo_categoria_literal'],evidence=dumps(proof));rows.append(tuple(d[n]for n in INTERNAL_FIELDS))
