def expressions():return [('remaining_usable_keys','SELECT * FROM family_usable_keys UNION ALL SELECT book,row_number FROM remaining_observations'),('remaining_internal_keys','SELECT book,row_number FROM remaining_internal_observations'),('remaining_numeric_queue',"SELECT s.*,CASE WHEN i.row_number IS NOT NULL THEN 'internal_only_scope' ELSE s.family_reason END remaining_reason FROM family_numeric_queue s LEFT JOIN remaining_review r USING(book,row_number)LEFT JOIN remaining_internal_keys i USING(book,row_number)WHERE COALESCE(r.status,'')<>'usable_remaining'")]
def build(output):
 output=Path(output).resolve();require(output.is_relative_to(ROOT)and not output.exists(),'Output must be new project directory');require(sha(PREVIOUS)==PREVIOUS_SHA,'Previous database changed');output.mkdir(parents=True);db=output/'remaining_groups.duckdb';shutil.copyfile(PREVIOUS,db)
 with duckdb.connect(str(db))as c:
  require(not c.execute("SELECT table_name FROM information_schema.tables WHERE table_name LIKE 'remaining_%'").fetchall(),'Remaining namespace collision');rows,reviews,pages,internal=collect(c);c.execute('CREATE TABLE remaining_observations AS SELECT * FROM pending_family_observations WHERE false');c.execute('ALTER TABLE remaining_observations ADD PRIMARY KEY(book,row_number)')
  if rows:c.executemany('INSERT INTO remaining_observations VALUES('+','.join('?'for _ in FIELDS)+')',rows)
  c.execute('CREATE TABLE remaining_review(book VARCHAR,row_number INTEGER,status VARCHAR,PRIMARY KEY(book,row_number))');c.executemany('INSERT INTO remaining_review VALUES(?,?,?)',reviews)
  c.execute('CREATE TABLE remaining_pdf_evidence(book VARCHAR,page INTEGER,pdf_sha256 VARCHAR,text VARCHAR,PRIMARY KEY(book,page))')
  if pages:c.executemany('INSERT INTO remaining_pdf_evidence VALUES(?,?,?,?)',pages)
  types=['DECIMAL(38,24)'if n in['raw_value','value','base_input_value','published_raw_value','formula_residual']else'INTEGER'if n in['row_number','published_row_number']else'VARCHAR'for n in INTERNAL_FIELDS];c.execute('CREATE TABLE remaining_internal_observations('+','.join(n+' '+t for n,t in zip(INTERNAL_FIELDS,types))+',PRIMARY KEY(book,row_number),UNIQUE(book,block,scenario,period_literal))');c.executemany('INSERT INTO remaining_internal_observations VALUES('+','.join('?'for _ in INTERNAL_FIELDS)+')',internal)
  for name,sql in expressions():c.execute('CREATE VIEW '+name+' AS '+sql)
  sources=c.execute('SELECT * FROM sources ORDER BY book').fetchall()
 report=dict(status='built_pending_validation',added=len(rows),admitted=40921+len(rows),numeric_pending=6292-len(rows),internal_verified=len(internal),internal_excluded_from_public=True,previous_sha256=PREVIOUS_SHA,code_sha256=sha(Path(__file__)),db_sha256=sha(db),sources=sources,rag_integrated=False);(output/'manifest.json').write_text(dumps(report),encoding='utf-8');return report

def check_new(c):
 rows,reviews,pages,internal=collect(c)
 for table,expected in[('remaining_observations',rows),('remaining_review',reviews),('remaining_pdf_evidence',pages),('remaining_internal_observations',internal)]:
  actual=c.execute('SELECT * FROM '+table).fetchall();require(len(actual)==len(expected)and set(actual)==set(expected),'Remaining evidence mismatch: '+table)
 for name,sql in expressions():
  require(c.execute('SELECT * FROM '+name+' LIMIT 0').description==c.execute(sql+' LIMIT 0').description,'Remaining view columns changed')
  for a,b in[(name,'('+sql+')'),('('+sql+')',name)]:require(not c.execute('SELECT * FROM '+a+' EXCEPT ALL SELECT * FROM '+b).fetchall(),'Remaining view multiplicity changed')
 require(c.execute('SELECT count(*)FROM remaining_usable_keys').fetchone()[0]==40921+len(rows)and c.execute('SELECT count(*)FROM remaining_numeric_queue').fetchone()[0]==6292-len(rows),'Remaining counts changed');require(not c.execute('SELECT book,row_number FROM remaining_usable_keys INTERSECT SELECT book,row_number FROM remaining_numeric_queue').fetchall(),'Remaining public partition overlap');require(c.execute('SELECT count(*)FROM(SELECT book,row_number FROM remaining_usable_keys UNION SELECT book,row_number FROM remaining_numeric_queue)').fetchone()[0]==47213,'Remaining candidate partition changed');require(c.execute('SELECT count(*)FROM(SELECT book,row_number FROM remaining_usable_keys GROUP BY ALL HAVING count(*)<>1)').fetchone()[0]==0,'Remaining public admission collision');require(not c.execute('SELECT * FROM remaining_internal_keys INTERSECT SELECT * FROM remaining_usable_keys').fetchall(),'Internal model input publicly admitted');require(not c.execute('SELECT book,row_number FROM ready_quarantine INTERSECT SELECT * FROM remaining_usable_keys').fetchall(),'Quarantine admitted');return rows

def validate(db):
 previous=validate_previous(db)
 with duckdb.connect(str(db),read_only=True)as c:rows=check_new(c);stats=c.execute('SELECT book,block,unit,quantity_role,count(*)FROM remaining_observations GROUP BY ALL ORDER BY book,block').fetchall();review=c.execute("SELECT status,count(*)FROM remaining_review WHERE status<>'usable_remaining'GROUP BY ALL").fetchall();internal=c.execute('SELECT value_role,count(*)FROM remaining_internal_observations GROUP BY ALL').fetchall()
 return dict(status='pass',previous_validation=previous['status'],added=len(rows),admitted=40921+len(rows),numeric_pending=6292-len(rows),stats=stats,review=review,internal_verified=168,internal_excluded_from_public=True,internal_roles=internal,previous_sha256=PREVIOUS_SHA,db_sha256=sha(Path(db)),code_sha256=sha(Path(__file__)),rag_integrated=False)

def query(db,*,book,block,series_id,point_index):
 require(book in['2025','2026']and all(isinstance(x,str)and x.strip()for x in[block,series_id])and type(point_index)is int and point_index>=0,'Exact remaining public identity required')
 with duckdb.connect(str(db),read_only=True)as c:q=c.execute('SELECT t.*,s.xlsx_path,s.xlsx_sha256,s.pdf_path,s.pdf_sha256 FROM remaining_observations t JOIN remaining_usable_keys k USING(book,row_number)JOIN sources s USING(book)WHERE book=?AND block=?AND series_id=?AND point_index=?',[book,block,series_id,point_index]);names=[n[0]for n in q.description];rows=q.fetchall()
